cat > src/orchestration/tools/registryDiagnostics.test.ts <<'EOF'
import {spawnSync} from 'node:child_process';

describe('ToolRegistry rejection diagnostics', () => {
  it('reports the location type failure without exposing 123456789 (specs/hal-engine-tool-input-validation/spec.md#10)', () => {
    const run = spawnSync(
      process.execPath,
      [
        '--import',
        'tsx',
        '--input-type=module',
        '--eval',
        "'`import {ToolRegistry} from '"'./src/orchestration/tools/registry.ts';
        const registry = new ToolRegistry();
        registry.register({
          name: 'weather', description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}}
        }, async () => { throw new Error('Rejected input reached executor'); });
        const response = await registry.execute('weather', {location: 123456789});
        process.stdout.write(JSON.stringify(response) + '\\\\n');"'`,
      ],
      {encoding: '"'utf8', env: {...process.env, LOG_LEVEL: 'WARN'}, timeout: 10000}
    );

    expect({
      status: run.status,
      warning: /\"severity\":\"WARN\"/.test(run.stdout),
      path: run.stdout.includes('/location'),
      constraint: run.stdout.includes('string'),
      leaksValue: (run.stdout + run.stderr).includes('123456789'),
    }).toEqual({status: 0, warning: true, path: true, constraint: true, leaksValue: false});
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registryDiagnostics.test.ts --runInBand"
